from datetime import date, datetime
from zoneinfo import ZoneInfo

import _market_calendar as calendar
import pytest


def test_supported_cash_equity_venues():
    assert calendar.supported_venues() == ("XLON", "XNAS", "XNYS", "XTKS")


def test_jpx_close_cutover_and_lunch_break():
    before = calendar.session_for_date("XTKS", date(2024, 11, 1))
    after = calendar.session_for_date("XTKS", date(2024, 11, 5))
    assert before.market_close.strftime("%H:%M") == "15:00"
    assert after.market_close.strftime("%H:%M") == "15:30"
    assert after.break_start.strftime("%H:%M") == "11:30"
    assert after.break_end.strftime("%H:%M") == "12:30"
    assert (
        calendar.is_open_at("XTKS", datetime(2024, 11, 5, 12, 0, tzinfo=ZoneInfo("Asia/Tokyo")))
        is False
    )


def test_us_holiday_early_close_and_dst():
    assert calendar.session_for_date("XNYS", date(2026, 4, 3)) is None
    early = calendar.session_for_date("XNYS", date(2026, 11, 27))
    assert early.market_close.strftime("%H:%M %z") == "13:00 -0500"
    winter = calendar.session_for_date("XNYS", date(2026, 1, 5))
    summer = calendar.session_for_date("XNAS", date(2026, 7, 6))
    assert winter.market_open.utcoffset().total_seconds() == -5 * 3600
    assert summer.market_open.utcoffset().total_seconds() == -4 * 3600


def test_lse_uses_dst_aware_timezone():
    winter = calendar.session_for_date("XLON", date(2026, 1, 5))
    summer = calendar.session_for_date("XLON", date(2026, 7, 6))
    assert winter.market_open.tzname() == "GMT"
    assert summer.market_open.tzname() == "BST"


def test_next_session_skips_weekend_and_holiday():
    session = calendar.next_session_on_or_after("XNYS", date(2026, 7, 3))
    assert session.session_date == date(2026, 7, 6)
    later = calendar.next_session_after("XNYS", date(2026, 7, 6))
    assert later.session_date == date(2026, 7, 7)


def test_previous_session_skips_weekend_and_holiday():
    session = calendar.previous_session_before("XNYS", date(2026, 7, 6))
    assert session.session_date == date(2026, 7, 2)
    same = calendar.previous_session_on_or_before("XNYS", date(2026, 7, 6))
    assert same.session_date == date(2026, 7, 6)


