def test_same_day_and_reverse_contracts():
    assert (
        calendar.count_sessions(
            "XNYS",
            date(2026, 7, 6),
            date(2026, 7, 6),
            include_start=True,
            include_end=True,
        )
        == 1
    )
    with pytest.raises(ValueError, match="on or before"):
        calendar.count_sessions(
            "XNYS",
            date(2026, 7, 7),
            date(2026, 7, 6),
            include_start=False,
            include_end=True,
        )


def test_naive_datetime_and_unknown_venue_fail_closed():
    with pytest.raises(ValueError, match="timezone-aware"):
        calendar.is_open_at("XNYS", datetime(2026, 7, 6, 10, 0))
    with pytest.raises(ValueError, match="Unsupported venue"):
        calendar.session_for_date("NOPE", date(2026, 7, 6))


def test_parse_aware_datetime_accepts_z_and_rejects_date_only():
    parsed = calendar.parse_aware_datetime("2026-07-06T14:00:00Z")
    assert parsed.utcoffset().total_seconds() == 0
    with pytest.raises(ValueError, match="timezone-aware"):
        calendar.parse_aware_datetime("2026-07-06")


def test_close_is_exclusive_and_current_session_rolls_forward():
    at_close = datetime(2026, 11, 27, 13, 0, tzinfo=ZoneInfo("America/New_York"))
    assert calendar.is_open_at("XNYS", at_close) is False
    assert calendar.current_or_next_session("XNYS", at_close).session_date == date(2026, 11, 30)


def test_provider_failure_is_not_treated_as_a_holiday(monkeypatch):
    def fail_provider(_venue):
        raise calendar.CalendarUnavailableError("calendar unavailable")

    monkeypatch.setattr(calendar, "_provider_calendar", fail_provider)
    with pytest.raises(calendar.CalendarUnavailableError, match="unavailable"):
        calendar.session_for_date("XNYS", date(2026, 7, 6))


def test_search_horizon_failure_is_explicit(monkeypatch):
    class EmptySchedule:
        empty = True

    monkeypatch.setattr(
        calendar,
        "_schedule",
        lambda venue, start, end: ("XNYS", "America/New_York", EmptySchedule()),
    )
    with pytest.raises(calendar.CalendarUnavailableError, match="No XNYS session"):
        calendar.next_session_on_or_after("XNYS", date(2026, 7, 6), max_search_days=1)
